public int checkWifiPassword(Editable editable) {
    boolean z = false;
    if (editable == null || editable.length() == 0) {
        ((FragmentConfigDeviceNetManagerBinding) this.binding).tvWifiPasswordErrorTip.setText(R.string.wifi_password_not_allow_empty);
        ((FragmentConfigDeviceNetManagerBinding) this.binding).tvWifiPasswordErrorTip.setVisibility(0);
        ((FragmentConfigDeviceNetManagerBinding) this.binding).btnSave.setEnabled(false);
        return 0;
    }
    if (editable.length() < 8) {
        ((FragmentConfigDeviceNetManagerBinding) this.binding).tvWifiPasswordErrorTip.setText(R.string.wifi_password_not_allow_less_than_min_lenght);
        ((FragmentConfigDeviceNetManagerBinding) this.binding).tvWifiPasswordErrorTip.setVisibility(0);
        ((FragmentConfigDeviceNetManagerBinding) this.binding).btnSave.setEnabled(false);
        return -1;
    }
    if (editable.length() > 30) {
        ((FragmentConfigDeviceNetManagerBinding) this.binding).tvWifiPasswordErrorTip.setText(R.string.wifi_password_not_allow_exceed_max_lenght);
        ((FragmentConfigDeviceNetManagerBinding) this.binding).tvWifiPasswordErrorTip.setVisibility(0);
        ((FragmentConfigDeviceNetManagerBinding) this.binding).btnSave.setEnabled(false);
        return -2;
    }
    ((FragmentConfigDeviceNetManagerBinding) this.binding).tvWifiPasswordErrorTip.setVisibility(8);
    Editable text = ((FragmentConfigDeviceNetManagerBinding) this.binding).layoutInputWifiName.etInput.getText();
    String strTrim = text != null ? text.toString().trim() : "";
    Button button = ((FragmentConfigDeviceNetManagerBinding) this.binding).btnSave;
    if (!strTrim.isEmpty() && strTrim.length() <= 30) {
        z = true;
    }
    button.setEnabled(z);
    return 1;
}
